final class Weak<T: AnyObject> { weak var value: T?; init(_ v: T) { value = v } }

final class Registry {
    private var listeners: [Weak<Listener>] = []

    func notifyAll(_ event: Event) {
        listeners = listeners.filter { $0.value != nil }   // reap dead
        listeners.forEach { $0.value?.onEvent(event) }      // promote + use
    }
}
